// The Bash commands the skills tell the desk to run (skills-desk-commands.ts, generated by skills-contract.mjs, which also checks the
// roles and tool names) must pass strict mode as written, placeholders filled in.
import { expect, test } from 'claude-code/testing'
import { deskBashOk } from './guard'
import { DESK_COMMANDS } from './skills-desk-commands'

const concrete = (c: string) => c.replace(/<[^>]*>/g, 'x')

test('every Bash command a skill tells the desk to run passes strict mode', () => {
  expect(DESK_COMMANDS.length).toBeGreaterThanOrEqual(5)
  for (const [skill, c] of DESK_COMMANDS) expect([skill, c, deskBashOk(concrete(c))]).toEqual([skill, c, true])
})

test('and strict mode still refuses what the pr skill gives to the thread', () => {
  for (const c of ['gh pr create --title <t> --body-file <f>', 'git push -u origin <branch>', 'gh api repos/{owner}/{repo}/pulls/<n>/comments', 'az repos pr create --title <t>', 'az repos pr update --id <n> --status abandoned', 'gh pr view <n> --json reviews,comments | head'])
    expect([c, deskBashOk(concrete(c))]).toEqual([c, false])
})
